import java.util.concurrent.atomic.AtomicInteger;

public class Main {
    private static int protege = 0;
    private static final AtomicInteger atomique = new AtomicInteger();

    static synchronized void incrementer() {
        protege++;
    }

    public static void main(String[] args) throws InterruptedException {
        Runnable travail = () -> {
            for (int i = 0; i < 10000; i++) {
                incrementer();
                atomique.incrementAndGet();
            }
        };

        Thread a = new Thread(travail);
        Thread b = new Thread(travail);
        a.start();
        b.start();
        a.join();
        b.join();

        System.out.println(protege);
        System.out.println(atomique.get());
    }
}

